32	// Run executes the deterministic subset of rules and refuses inputs they need.
33	func Run(artifact Artifact, rules []Rule, invariants map[string]bool) ([]Finding, error) {
34		if artifact.Name == "" {
35			return nil, errInvalid("artifact name is required")
36		}
37		var findings []Finding
38		for _, rule := range rules {
39			if rule.RequiresABI && artifact.ABI == "" {
