47					Invariant: rule.Invariant, Evidence: "invariant " + rule.Invariant + " does not hold"})
48			}
49		}
50		sort.Slice(findings, func(i, j int) bool {
51			if findings[i].Severity == findings[j].Severity {
52				return findings[i].Rule < findings[j].Rule
53			}
54			return findings[i].Severity > findings[j].Severity
