1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13	)
14	
15	// Check statuses recorded per rule in a report.
16	const (
17		StatusUnchecked   = "未检查"
18		StatusPass        = "通过"
19		StatusDefect      = "发现缺陷"
20		StatusToolMissing = "工具缺失"
21		StatusTimeout     = "超时"
22	)
23	
24	// ReportArtifact identifies the audited artifact by name and content hash.
25	type ReportArtifact struct {
26		Name string `json:"name"`
27		Hash string `json:"hash"`
28	}
29	
30	// ReportRule is one rule together with the invariant check result. The note
31	// carries the original checker description: counterexample evidence for a
32	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
33	// or an optional remark for a passing check. It is empty for reports built
34	// only from invariant booleans.
35	type ReportRule struct {
36		ID          string `json:"id"`
37		Kind        string `json:"kind"`
38		Severity    string `json:"severity"`
39		Invariant   string `json:"invariant"`
40		RequiresABI bool   `json:"requiresABI"`
41		Version     string `json:"version"`
42		Status      string `json:"status"`
43		Note        string `json:"note,omitempty"`
44	}
45	
46	// ReportFinding binds a defect to its artifact, rule, version and evidence.
47	type ReportFinding struct {
48		ArtifactHash string `json:"artifactHash"`
49		RuleID       string `json:"ruleId"`
50		Version      string `json:"version"`
51		Severity     string `json:"severity"`
52		Invariant    string `json:"invariant"`
53		Evidence     string `json:"evidence"`
54	}
55	
56	// Report is the persisted audit result.
57	type Report struct {
58		ReportID string          `json:"reportId"`
59		Artifact ReportArtifact  `json:"artifact"`
60		Rules    []ReportRule    `json:"rules"`
61		Findings []ReportFinding `json:"findings"`
62	}
63	
64	// wireArtifact is the JSON shape of an artifact in an audit submission.
65	type wireArtifact struct {
66		Name     string `json:"name"`
67		ABI      string `json:"abi"`
68		Bytecode string `json:"bytecode"`
69		Source   string `json:"source"`
70	}
71	
72	// wireRule is the JSON shape of a rule in an audit submission.
73	type wireRule struct {
74		ID          string `json:"id"`
75		Kind        string `json:"kind"`
76		Severity    string `json:"severity"`
77		Invariant   string `json:"invariant"`
78		RequiresABI bool   `json:"requiresABI"`
79		Version     string `json:"version"`
80	}
81	
82	// CheckRecord is one imported per-rule check result: the artifact hash and
83	// rule version it was produced against, the conclusion status, and the
84	// original checker note (counterexample, tool or deadline remark).
85	type CheckRecord struct {
86		ArtifactHash string
87		RuleID       string
88		Version      string
89		Status       string
90		Note         string
91	}
92	
93	// wireCheck is the JSON shape of one entry in the checks array.
94	type wireCheck struct {
95		ArtifactHash string `json:"artifactHash"`
96		RuleID       string `json:"ruleId"`
97		Version      string `json:"version"`
98		Status       string `json:"status"`
99		Note         string `json:"note"`
100	}
101	
102	// wireInput is the JSON object accepted by the audit command.
103	type wireInput struct {
104		Artifact   wireArtifact               `json:"artifact"`
105		Rules      []wireRule                 `json:"rules"`
106		Invariants map[string]json.RawMessage `json:"invariants"`
107		Checks     []wireCheck                `json:"checks"`
108	}
109	
110	// ParseAuditInput decodes an audit submission JSON object into domain values.
111	// Invariant values must be JSON booleans; any other type is an error.
112	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
113		var in wireInput
114		if err := json.Unmarshal(data, &in); err != nil {
115			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
116		}
117		invariants := make(map[string]bool, len(in.Invariants))
118		for key, raw := range in.Invariants {
119			var holds bool
120			if err := json.Unmarshal(raw, &holds); err != nil {
121				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
122			}
123			invariants[key] = holds
124		}
125		artifact := Artifact{
126			Name:     in.Artifact.Name,
127			ABI:      in.Artifact.ABI,
128			Bytecode: in.Artifact.Bytecode,
129			Source:   in.Artifact.Source,
130		}
131		rules := make([]Rule, 0, len(in.Rules))
132		for _, wr := range in.Rules {
133			rules = append(rules, Rule{
134				ID:          wr.ID,
135				Kind:        wr.Kind,
136				Severity:    wr.Severity,
137				Invariant:   wr.Invariant,
138				RequiresABI: wr.RequiresABI,
139				Version:     wr.Version,
140			})
141		}
142		checks := make([]CheckRecord, 0, len(in.Checks))
143		for _, wc := range in.Checks {
144			checks = append(checks, CheckRecord{
145				ArtifactHash: wc.ArtifactHash,
146				RuleID:       wc.RuleID,
147				Version:      wc.Version,
148				Status:       wc.Status,
149				Note:         wc.Note,
150			})
151		}
152		return artifact, rules, invariants, checks, nil
153	}
154	
155	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
156	// bytecode and source strings contribute; field boundaries are explicit
157	// (length-prefixed) so that different splits never collide. The source is
158	// hashed as a field value, never read from disk, and the name does not
159	// participate.
160	func ArtifactHash(a Artifact) string {
161		h := sha256.New()
162		h.Write([]byte("contractsentinel-artifact-v1\n"))
163		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
164			fmt.Fprintf(h, "%d\n", len(field))
165			h.Write([]byte(field))
166		}
167		sum := h.Sum(nil)
168		return hex.EncodeToString(sum)
169	}
170	
171	// validCheckStatus reports whether status is one of the four recorded check
172	// conclusions.
173	func validCheckStatus(status string) bool {
174		switch status {
175		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
176			return true
177		}
178		return false
179	}
180	
181	// BuildReport evaluates rules against the artifact and invariant values and
182	// imported check records and produces the report to persist. Insufficient
183	// inputs (missing ABI for a rule that requires it, missing bytecode for a
184	// symbolic rule) fail the whole submission and are never recorded as defects.
185	// Imported checks are validated as a whole: unknown rules, duplicate records,
186	// unknown statuses, missing notes, hash or version mismatches, and a rule
187	// receiving both a check record and an invariant boolean all reject the
188	// submission without producing a report.
189	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
190		if artifact.Name == "" {
191			return Report{}, errInvalid("artifact name is required")
192		}
193		hash := ArtifactHash(artifact)
194		seen := make(map[string]bool, len(rules))
195		ruleByID := make(map[string]Rule, len(rules))
196		for _, rule := range rules {
197			if rule.ID == "" {
198				return Report{}, errInvalid("rule id is required")
199			}
200			if rule.Version == "" {
201				return Report{}, errInvalid("rule " + rule.ID + " version is required")
202			}
203			if seen[rule.ID] {
204				return Report{}, errInvalid("duplicate rule id " + rule.ID)
205			}
206			seen[rule.ID] = true
207			ruleByID[rule.ID] = rule
208			if rule.RequiresABI && artifact.ABI == "" {
209				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
210			}
211			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
212				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
213			}
214		}
215		checkByRule := make(map[string]CheckRecord, len(checks))
216		for _, check := range checks {
217			if check.RuleID == "" {
218				return Report{}, errInvalid("check rule id is required")
219			}
220			rule, ok := ruleByID[check.RuleID]
221			if !ok {
222				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
223			}
224			if _, dup := checkByRule[check.RuleID]; dup {
225				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
226			}
227			if check.ArtifactHash != hash {
228				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
229			}
230			if check.Version != rule.Version {
231				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
232			}
233			if !validCheckStatus(check.Status) {
234				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
235			}
236			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
237				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
238			}
239			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
240				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
241			}
242			checkByRule[check.RuleID] = check
243		}
244		report := Report{
245			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
246			Rules:    []ReportRule{},
247			Findings: []ReportFinding{},
248		}
249		for _, rule := range rules {
250			status := StatusUnchecked
251			note := ""
252			if check, ok := checkByRule[rule.ID]; ok {
253				status = check.Status
254				note = check.Note
255			} else if holds, checked := invariants[rule.Invariant]; checked {
256				if holds {
257					status = StatusPass
258				} else {
259					status = StatusDefect
260				}
261			}
262			report.Rules = append(report.Rules, ReportRule{
263				ID:          rule.ID,
264				Kind:        rule.Kind,
265				Severity:    rule.Severity,
266				Invariant:   rule.Invariant,
267				RequiresABI: rule.RequiresABI,
268				Version:     rule.Version,
269				Status:      status,
270				Note:        note,
271			})
272			if status == StatusDefect {
273				evidence := note
274				if evidence == "" {
275					evidence = "invariant " + rule.Invariant + " does not hold"
276				}
277				report.Findings = append(report.Findings, ReportFinding{
278					ArtifactHash: hash,
279					RuleID:       rule.ID,
280					Version:      rule.Version,
281					Severity:     rule.Severity,
282					Invariant:    rule.Invariant,
283					Evidence:     evidence,
284				})
285			}
286		}
287		report.ReportID = ReportID(report)
288		return report, nil
289	}
290	
291	// canonicalRule is the order-independent view of a rule used for the id. The
292	// note is omitted when empty so reports built only from invariant booleans
293	// keep their original ids.
294	type canonicalRule struct {
295		ID          string `json:"id"`
296		Kind        string `json:"kind"`
297		Severity    string `json:"severity"`
298		Invariant   string `json:"invariant"`
299		RequiresABI bool   `json:"requiresABI"`
300		Version     string `json:"version"`
301		Status      string `json:"status"`
302		Note        string `json:"note,omitempty"`
303	}
304	
305	// canonicalFinding is the order-independent view of a finding used for the id.
306	type canonicalFinding struct {
307		ArtifactHash string `json:"artifactHash"`
308		RuleID       string `json:"ruleId"`
309		Version      string `json:"version"`
310		Severity     string `json:"severity"`
311		Invariant    string `json:"invariant"`
312		Evidence     string `json:"evidence"`
313	}
314	
315	// canonicalReport is the deterministic content a report id is computed from.
316	type canonicalReport struct {
317		ArtifactHash string             `json:"artifactHash"`
318		Name         string             `json:"name"`
319		Rules        []canonicalRule    `json:"rules"`
320		Findings     []canonicalFinding `json:"findings"`
321	}
322	
323	// canonicalize renders a report into its order-independent form.
324	func canonicalize(report Report) canonicalReport {
325		cr := canonicalReport{
326			ArtifactHash: report.Artifact.Hash,
327			Name:         report.Artifact.Name,
328		}
329		for _, rule := range report.Rules {
330			cr.Rules = append(cr.Rules, canonicalRule{
331				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
332				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
333				Version: rule.Version, Status: rule.Status, Note: rule.Note,
334			})
335		}
336		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
337		for _, finding := range report.Findings {
338			cr.Findings = append(cr.Findings, canonicalFinding{
339				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
340				Version: finding.Version, Severity: finding.Severity,
341				Invariant: finding.Invariant, Evidence: finding.Evidence,
342			})
343		}
344		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
345		return cr
346	}
347	
348	// ReportID returns the content-addressed identifier of a report. The id binds
349	// the artifact hash, name, complete rule definitions, the invariant value
350	// used by each rule (unchecked and explicit pass are distinct), and the
351	// findings. Rule order, invariant key order and unrelated invariant keys do
352	// not influence it.
353	func ReportID(r Report) string {
354		data, err := json.Marshal(canonicalize(r))
355		if err != nil {
356			panic(err) // canonical values are all strings and bools
357		}
358		sum := sha256.Sum256(data)
359		return hex.EncodeToString(sum[:])
360	}
361	
362	// validateReport checks every archive legality condition against r. It is the
363	// single definition of a legal report: the id and artifact hash are 64
364	// lowercase hex characters, the id matches the content, the artifact name is
365	// present, rule ids are present and unique with non-empty versions, statuses
366	// use the five recorded values, tool-missing and timeout notes are
367	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
368	// artifact hash, version, severity, invariant and evidence match the rule.
369	// The same conditions apply to submissions and to stored archives: a
370	// recomputed id never makes an invalid report legal. fail is errInvalid for
371	// submissions and errCorrupt for stored archives.
372	func validateReport(r Report, fail func(string) error) error {
373		if !validReportID(r.ReportID) {
374			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
375		}
376		if r.Artifact.Name == "" {
377			return fail("report " + r.ReportID + " artifact name is required")
378		}
379		if !validReportID(r.Artifact.Hash) {
380			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
381		}
382		if ReportID(r) != r.ReportID {
383			return fail("report content does not match id " + r.ReportID)
384		}
385		seenRule := make(map[string]bool, len(r.Rules))
386		defectByID := make(map[string]ReportRule)
387		for _, rule := range r.Rules {
388			if rule.ID == "" {
389				return fail("report " + r.ReportID + " has a rule with an empty id")
390			}
391			if seenRule[rule.ID] {
392				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
393			}
394			seenRule[rule.ID] = true
395			if rule.Version == "" {
396				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
397			}
398			switch rule.Status {
399			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
400			default:
401				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
402			}
403			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
404				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
405			}
406			if rule.Status == StatusDefect {
407				defectByID[rule.ID] = rule
408			}
409		}
410		seenFinding := make(map[string]bool, len(r.Findings))
411		for _, f := range r.Findings {
412			if f.RuleID == "" {
413				return fail("report " + r.ReportID + " has a finding with an empty rule id")
414			}
415			rule, ok := defectByID[f.RuleID]
416			if !ok {
417				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
418			}
419			if seenFinding[f.RuleID] {
420				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
421			}
422			seenFinding[f.RuleID] = true
423			if f.ArtifactHash != r.Artifact.Hash {
424				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
425			}
426			if f.Version != rule.Version {
427				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
428			}
429			if f.Severity != rule.Severity {
430				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
431			}
432			if f.Invariant != rule.Invariant {
433				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
434			}
435			wantEvidence := rule.Note
436			if wantEvidence == "" {
437				wantEvidence = "invariant " + rule.Invariant + " does not hold"
438			}
439			if f.Evidence != wantEvidence {
440				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
441			}
442		}
443		for id := range defectByID {
444			if !seenFinding[id] {
445				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
446			}
447		}
448		return nil
449	}
450	
451	// validStoredReport validates archive contents.
452	func validStoredReport(r Report) error {
453		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
454	}
455	
456	// validSubmittedReport validates a submission before any store operation.
457	func validSubmittedReport(r Report) error {
458		return validateReport(r, func(msg string) error { return errInvalid(msg) })
459	}
460	
461	// loadStoredReport parses archive bytes for id and fully validates them.
462	func loadStoredReport(data []byte, id string) (Report, error) {
463		var r Report
464		if err := json.Unmarshal(data, &r); err != nil {
465			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
466		}
467		if r.ReportID != id {
468			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
469		}
470		if err := validStoredReport(r); err != nil {
471			return Report{}, err
472		}
473		return r, nil
474	}
475	
476	// saveReportHook, when set, is invoked after the archive existence check and
477	// before the atomic publish. It lets tests simulate another process racing to
478	// claim the same report id.
479	var saveReportHook func(finalPath string)
480	
481	// SaveReport persists a report under the store directory. The store is safe
482	// for concurrent writers: identical reports share one file and all
483	// submissions succeed, different reports never overwrite each other, and
484	// readers only ever observe complete files. A submission is fully validated
485	// before any store operation, so an invalid report creates no store and no
486	// files. A pre-existing file with the same id must be a valid archive of the
487	// same report; a corrupted archive makes the submission fail while keeping the
488	// original file, even when the corruption appears only during the save. The
489	// first successfully archived bytes are never replaced by later submissions.
490	func SaveReport(dir string, r Report) error {
491		if err := validSubmittedReport(r); err != nil {
492			return err
493		}
494		if err := os.MkdirAll(dir, 0o755); err != nil {
495			return err
496		}
497		finalPath := filepath.Join(dir, r.ReportID+".json")
498		if existing, err := os.ReadFile(finalPath); err == nil {
499			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
500				return err
501			}
502			return nil
503		} else if !os.IsNotExist(err) {
504			return err
505		}
506		data, err := json.Marshal(r)
507		if err != nil {
508			return err
509		}
510		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
511		if err != nil {
512			return err
513		}
514		tmpPath := tmp.Name()
515		cleanup := func() { os.Remove(tmpPath) }
516		if _, err := tmp.Write(data); err != nil {
517			tmp.Close()
518			cleanup()
519			return err
520		}
521		if err := tmp.Sync(); err != nil {
522			tmp.Close()
523			cleanup()
524			return err
525		}
526		if err := tmp.Close(); err != nil {
527			cleanup()
528			return err
529		}
530		if saveReportHook != nil {
531			saveReportHook(finalPath)
532		}
533		if err := os.Link(tmpPath, finalPath); err != nil {
534			cleanup()
535			if os.IsExist(err) {
536				existing, readErr := os.ReadFile(finalPath)
537				if readErr != nil {
538					return readErr
539				}
540				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
541					return err
542				}
543				return nil
544			}
545			return err
546		}
547		cleanup()
548		return nil
549	}
550	
551	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
552	// hex characters; missing, corrupted or tampered archives produce a clear
553	// error. The store is only read, never created or modified.
554	func LoadReport(dir, id string) (Report, error) {
555		if !validReportID(id) {
556			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
557		}
558		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
559		if err != nil {
560			if os.IsNotExist(err) {
561				return Report{}, errNotFound("report " + id + " not found")
562			}
563			return Report{}, err
564		}
565		return loadStoredReport(data, id)
566	}
567	
568	type errNotFound string
569	
570	func (e errNotFound) Error() string { return string(e) }
571	
572	type errCorrupt string
573	
574	func (e errCorrupt) Error() string { return string(e) }
